ensureDialog('projectDialog','Project','PROJECT DASHBOARD',`<form id="projectForm"><input id="projectId" type="hidden"><div class="ops-form-grid"><label>Name<input id="projectName" required></label><label>Status<select id="projectStatus"><option>Active</option><option>Planning</option><option>On hold</option><option>Complete</option></select></label><label class="wide">Central hypothesis / objective<textarea id="projectHypothesis"></textarea></label><label>Owner / lead<input id="projectOwner"></label><label>Next milestone<input id="projectMilestone"></label><label class="wide">Current blockers<textarea id="projectBlockers"></textarea></label><label class="wide">Project notes<textarea id="projectNotes"></textarea></label></div><button class="primary">Save project</button></form>`);
